struct DescendingInt {
    bool operator()(const int& a, const int& b) const {
        return a > b; // Defines descending order
    }
};

// Default comparison (std::less<int>)
std::set<int> s_asc = {5, 1};

// Standard library specialization
std::set<int, std::greater<int>> s_std_desc = {5, 1};

// Custom struct specialization
std::set<int, DescendingInt> s_custom_desc = {5, 1};
